// Add custom regex validation method for city name (letters and spaces only)
jQuery.validator.addMethod(
    "lettersSpacesOnly",
    function (value, element) {
        return this.optional(element) || /^[A-Za-z\s]+$/.test(value);
    },
    "City name must contain only letters and spaces."
);

jQuery(function () {
    // Initialize form validation for city form
    $(".js-validation-district").validate({
        rules: {
            district_name: {
                required: true,
                maxlength: 30,
                lettersSpacesOnly: true,
            },
            state_id: {
                required: true,
            },
            status: {
                required: true,
            },
        },
        messages: {
            district_name: {
                required: "Please enter a District name.",
                maxlength: "District name cannot exceed 30 characters.",
                lettersSpacesOnly:
                    "District name must contain only letters and spaces.",
            },
            state_id: {
                required: "Please select a state.",
            },
            status: {
                required: "Please select a status.",
            },
        },
        errorClass: "is-invalid",
        validClass: "is-valid",
        errorElement: "div",
        highlight: function (element) {
            $(element).addClass("is-invalid").removeClass("is-valid");
        },
        unhighlight: function (element) {
            $(element).addClass("is-valid").removeClass("is-invalid");
        },
        errorPlacement: function (error, element) {
            error.addClass("invalid-feedback");
            // Dashmix: Place error after input inside .form-group or .mb-3
            if (element.parent(".input-group").length) {
                element.parent().after(error);
            } else if (element.closest(".form-group").length) {
                element.closest(".form-group").append(error);
            } else if (element.closest(".mb-3").length) {
                element.closest(".mb-3").append(error);
            } else {
                element.after(error);
            }
        },
        submitHandler: function (form) {
            form.submit();
        },
        invalidHandler: function (_, validator) {
            if (validator.errorList.length) {
                $(validator.errorList[0].element).trigger("focus");
            }
        },
    });

    // Prevent manual submission if invalid
    $(".js-validation-district").on("submit", function (e) {
        if (!$(this).valid()) {
            e.preventDefault();
        }
    });
});
